// oxlint-config-alexandernanberg ships untyped JS configs.
declare module 'oxlint-config-alexandernanberg/oxlint/react' {
  import type { OxlintConfig } from 'oxlint'
  const config: OxlintConfig
  export default config
}

declare module 'oxlint-config-alexandernanberg/oxfmt/base' {
  import type { OxfmtConfig } from 'oxfmt'
  const config: OxfmtConfig
  export default config
}
